let enhancedLoader;function initializeCompression(){try{enhancedLoader=new EnhancedDataLoader();enhancedLoader.init();console.log('✅ Enhanced compression system initialized');return true;}catch(error){console.error('❌ Failed to initialize compression system:',error);return false;}}async function loadInitialData(){try{showLoading();if(!enhancedLoader){initializeCompression();}console.log('📚 Loading surah names with compression...');if(enhancedLoader){appData.surahNames=await enhancedLoader.loadSurahNames();}else{const surahNamesResponse=await fetch('./data/surah_name.json');if(!surahNamesResponse.ok){throw new Error('Failed to fetch surah names');}appData.surahNames=await surahNamesResponse.json();}console.log('✅ Surah names loaded successfully');renderSurahList();const lastReadSurah=parseInt(localStorage.getItem('lastReadSurah'))||1;showLastSurahSuggestion(lastReadSurah);setTimeout(()=>{if(enhancedLoader){preloadPopularSurahsEnhanced();}else{preloadPopularSurahs();}},1000);hideLoading();}catch(error){hideLoading();showToast('Failed to load data. Please check your connection.','error');console.error('Data loading error:',error);}}async function loadSurahData(surahId){const surahIdStr=surahId.toString();if(surahCache.has(surahIdStr)){console.log(`📖 Surah ${surahId}loaded from memory cache`);return surahCache.get(surahIdStr);}if(loadingPromises.has(surahIdStr)){return loadingPromises.get(surahIdStr);}const loadingPromise=(async()=>{try{let surahData;if(enhancedLoader){surahData=await enhancedLoader.loadSurahData(surahId);}else{const surahFile=`surah_${surahIdStr.padStart(3,'0')}.json`;const response=await fetch(`./data/surahs/${surahFile}`);if(!response.ok){throw new Error(`HTTP ${response.status}: Failed to fetch surah ${surahId}`);}surahData=await response.json();}surahCache.set(surahIdStr,surahData);preloadAdjacentSurahs(parseInt(surahId));return surahData;}catch(error){console.error(`❌ Failed to load Surah ${surahId}:`,error);throw error;}finally{loadingPromises.delete(surahIdStr);}})();loadingPromises.set(surahIdStr,loadingPromise);return loadingPromise;}async function preloadPopularSurahsEnhanced(){if(!enhancedLoader){console.log('⚠️ Enhanced loader not available,using standard preloading');return preloadPopularSurahs();}const popularSurahs=[1,2,18,36,55,67,112,113,114];console.log('📚 Enhanced preloading of popular surahs...');try{await enhancedLoader.preloadSurahs(popularSurahs,{maxConcurrent: 2,showProgress: true});for(const surahId of popularSurahs){try{const cacheKey=`surah_${surahId}_compressed`;const data=await enhancedLoader.compressor.retrieveCompressedData(cacheKey);if(data){surahCache.set(surahId.toString(),data);}}catch(error){console.log(`⚠️ Could not cache Surah ${surahId}in memory:`,error.message);}}console.log('🎉 Enhanced preloading completed successfully');}catch(error){console.error('❌ Enhanced preloading failed:',error);preloadPopularSurahs();}}window.compressionUtils={async testPerformance(){if(!enhancedLoader){console.error('❌ Enhanced loader not initialized');return;}return await enhancedLoader.testPerformance();},getCacheStats(){if(!enhancedLoader){console.error('❌ Enhanced loader not initialized');return;}return enhancedLoader.getCacheStats();},clearCache(){if(!enhancedLoader){console.error('❌ Enhanced loader not initialized');return false;}return enhancedLoader.clearCache();},showStats(){console.log('\n📊 COMPRESSION SYSTEM STATUS');console.log('═'.repeat(50));console.log(`Enhanced Loader: ${enhancedLoader ? '✅' : '❌'}`);console.log(`Pako Library: ${typeof pako!=='undefined' ? '✅' : '❌'}`);console.log(`Compression Enabled: ${enhancedLoader?.useCompression ? '✅' : '❌'}`);if(enhancedLoader){const stats=enhancedLoader.getCacheStats();console.log(`Cache Size: ${stats.size}`);console.log(`Cached Items: ${stats.count}`);console.log(`Cache Version: ${stats.version}`);}console.log('═'.repeat(50));console.log('💡 Available commands:');console.log(' compressionUtils.testPerformance()-Test loading speed');console.log(' compressionUtils.getCacheStats()-Get cache information');console.log(' compressionUtils.clearCache()-Clear compressed cache');}};document.addEventListener('DOMContentLoaded',()=>{initializeCompression();setTimeout(()=>{window.compressionUtils.showStats();},2000);});if(typeof window.loadInitialData==='function'){window.originalLoadInitialData=window.loadInitialData;window.loadInitialData=loadInitialData;}if(typeof window.loadSurahData==='function'){window.originalLoadSurahData=window.loadSurahData;window.loadSurahData=loadSurahData;}console.log('🔧 Migration patch loaded-Enhanced compression system ready!');